import asyncio, hashlib, inspect, json, os, tempfile, textwrap, time
from dataclasses import asdict
from pathlib import Path
from unittest.mock import patch

OUT=Path('.dev/gc-unlocked-fetch-probe.json');assert not OUT.exists()
out={'contract':'pa.gc-unlocked-fetch-probe/v1','scope':'New post-PR518 hypothesis: fetchall ONLY speculative positive query, maximum128rows. Original fresh locked recheck/pins/unlink/error/transaction unchanged. Earlier pre-PR518 fetchall p95 regression and invalid empty SQL trace remain retained, not overturned by assumption. Real worker/default budgets; sequential alternating pairs on all-live12511,mixed257+257,orphan513 and concurrent hot appends. No live state/provider/peer/backup/workload injection. Host activity uncontrolled; not representative acceptance or physical IO attribution. Every trial/error checkpointed before next invocation.','cases':[],'seeding':[]}
def save():
 raw=json.dumps(out,indent=2)+'\n';sha=hashlib.sha256(raw.encode()).hexdigest()
 OUT.with_name(OUT.stem+'.'+sha+'.json').write_text(raw);OUT.write_text(raw)

with tempfile.TemporaryDirectory(prefix='pa-gc-unlocked-fetch-') as temporary:
 root=Path(temporary);os.environ['PA_DATA_DIR']=str(root/'data');os.environ['PA_WORKSPACE_ROOT']=str(root/'workspaces');(root/'data').mkdir()
 from pa.repository.workspace import WorkspaceManager
 def deny(*a,**k):raise AssertionError('No workspace construction in GC fixture')
 WorkspaceManager.__init__=deny
 from pa.domain.transcript_storage import TranscriptStorage
 from pa.domain.models import TranscriptEvent
 from pa.core.async_runtime import AsyncRuntime
 from pa.core.performance import current_observation,distribution
 original=TranscriptStorage.collect_unreferenced_objects
 source=textwrap.dedent(inspect.getsource(original))
 needle='f"SELECT hash FROM transcript_objects WHERE ref_count>0 AND hash IN ({marks})", digests,\n            )}'
 assert source.count(needle)==2
 candidate_source=source.replace(needle,needle[:-1]+'.fetchall()}',1)
 # Match the exact first query, never the later authoritative locked query.
 assert candidate_source.count('.fetchall()')==1 and candidate_source.split('candidates =')[1]==source.split('candidates =')[1]
 scope={};exec(compile(candidate_source,'<gc-unlocked-fetch>','exec'),original.__globals__,scope);candidate=scope['collect_unreferenced_objects']
 out.update(source_sha256=hashlib.sha256(source.encode()).hexdigest(),candidate_source=candidate_source,candidate_sha256=hashlib.sha256(candidate_source.encode()).hexdigest(),roots={'PA_DATA_DIR':str(root/'data'),'PA_WORKSPACE_ROOT':str(root/'workspaces'),'workspace_construction':'denied'})
 def event(session,i,prefix='live',cold=True):return TranscriptEvent(session_id=session,seq=i+1,event_type='chunk',payload={'text':prefix+str(i)+(' cold fixture'*300 if cold else ' hot fixture')})
 def seed(s,session,n,prefix):
  for start in range(0,n,256):
   s.append([event(session,i,prefix) for i in range(start,min(start+256,n))]);out['seeding'].append({'session':session,'through':min(start+256,n)});save()
 def restore(s,n):
  if n:
   s.append([event('expired',i,'orphan') for i in range(n)])
   with s.retain_objects():assert s.prune(['expired'],keep_audit=False)==n
 fixtures={}
 for label,nlive,norphan in [('live',12511,0),('mixed',257,257),('orphan',0,513)]:
  s=TranscriptStorage(root/'data'/(label+'.db'));seed(s,'retained',nlive,'live');fixtures[label]=(s,nlive,norphan)
 async def run():
  runtime=AsyncRuntime()
  try:
   # A real nonempty trace attached to every newly created worker connection.
   traces=[];s=fixtures['live'][0]
   for label,method in [('baseline',original),('candidate',candidate)]:
    trace=[];factory=s._new_connection
    def traced():
     c=factory();c.set_trace_callback(lambda sql:trace.append(hashlib.sha256(sql.encode()).hexdigest()));return c
    with patch.object(s,'_new_connection',traced):assert await runtime.run_blocking('probe.gc_unlocked_trace',method,s)==0
    traces.append(trace)
   assert len(traces[0])>90 and traces[0]==traces[1]
   out['sql_trace_parity']={'count':len(traces[0]),'equal':True,'sha256':hashlib.sha256(json.dumps(traces[0]).encode()).hexdigest()};save()
   for workload,(s,nlive,norphan) in fixtures.items():
    for pair in range(10):
     order=[('baseline',original),('candidate',candidate)]
     if pair%2:order.reverse()
     for label,method in order:
      restore(s,norphan)
      def call():
       start=time.perf_counter();cpu=time.thread_time();removed=method(s)
       return {'wall_ms':(time.perf_counter()-start)*1000,'cpu_ms':(time.thread_time()-cpu)*1000,'removed':removed,'observed':{k:v for k,v in asdict(current_observation.get()).items() if isinstance(v,(int,float,bool))}}
      started=time.perf_counter()
      try:
       result=await runtime.run_blocking('probe.gc_unlocked_'+label,call);assert result['removed']==norphan
       out['cases'].append({'workload':workload,'pair':pair,'method':label,'caller_wall_ms':(time.perf_counter()-started)*1000,**result});save()
      except BaseException as exc:out['cases'].append({'workload':workload,'pair':pair,'method':label,'error_type':type(exc).__name__});save();raise
   s=fixtures['live'][0];seq=0
   for pair in range(3):
    order=[('baseline',original),('candidate',candidate)]
    if pair%2:order.reverse()
    for label,method in order:
     offset=seq;seq+=1024
     def writes():
      started=time.perf_counter()
      for i in range(64):s.append([event('hot',offset+i*16+j,'hot',False) for j in range(16)])
      return {'wall_ms':(time.perf_counter()-started)*1000,'events':1024}
     def gc():
      start=time.perf_counter();cpu=time.thread_time();removed=method(s)
      return {'wall_ms':(time.perf_counter()-start)*1000,'cpu_ms':(time.thread_time()-cpu)*1000,'removed':removed,'observed':{k:v for k,v in asdict(current_observation.get()).items() if isinstance(v,(int,float,bool))}}
     values=await asyncio.gather(runtime.run_blocking('probe.gc_unlocked_'+label,gc),runtime.run_blocking('probe.gc_unlocked_append',writes))
     assert values[0]['removed']==0 and values[1]['events']==1024
     out['cases'].append({'workload':'concurrent','pair':pair,'method':label,**values[0],'append':values[1]});save()
   out['runtime']=runtime.snapshot()
  finally:await runtime.close()
 asyncio.run(run())
 # Full final durable row/file hash checks are outside all measurement intervals.
 for workload,(s,nlive,norphan) in fixtures.items():
  with s._conn() as c:
   assert c.execute('SELECT COUNT(*) FROM transcript_events WHERE session_id=?',('retained',)).fetchone()[0]==nlive
   assert c.execute('SELECT COUNT(*) FROM transcript_events WHERE session_id=?',('expired',)).fetchone()[0]==0
   assert c.execute('SELECT COUNT(*) FROM transcript_objects WHERE ref_count>0').fetchone()[0]==nlive
  assert len(list(s.objects_dir.glob('*/*.zlib')))==nlive
  assert len(s.referenced_hashes())==nlive
  import zlib
  for p in s.objects_dir.glob('*/*.zlib'):assert hashlib.sha256(zlib.decompress(p.read_bytes())).hexdigest()==p.parent.name+p.stem
 out['durable_validation']={'retained_cold_hashes':sum(v[1] for v in fixtures.values()),'ordered_hot_events':6144,'all_cold_file_hashes_verified':True}
 s=fixtures['live'][0];hot=s.list('hot',limit=7000);assert [e.seq for e in hot]==list(range(1,6145))
 out['summary']={w:{m:{k:distribution([x[k] for x in out['cases'] if x['workload']==w and x['method']==m]) for k in ('wall_ms','cpu_ms')} for m in ('baseline','candidate')} for w in ('live','mixed','orphan','concurrent')};save()
 print(json.dumps({'summary':out['summary'],'sql_trace_parity':out['sql_trace_parity'],'trials':len(out['cases']),'output':str(OUT)}))

